  const wall = g.createLinearGradient(0, 0, 0, 480);
  wall.addColorStop(0, '#f9e9c8');
  wall.addColorStop(0.62, '#f2ddb7');
  wall.addColorStop(1, '#ead1a7');
  g.fillStyle = wall;
  g.fillRect(0, 0, DESIGN_W, 480);

