  // plants
  drawPlant(g, 26, 570, 1.05, '#ff6b57');
  drawPlant(g, 1152, 570, 1.0, '#ffc857');
  drawPlant(g, 330, 476, 0.55, '#8bd6b8');

  // floor scuffs
