'use strict';

function bindEvents() {
  const start = $('#startGame');
  if (start) {
    start.addEventListener('click', () => {
      ensureAudio();
      sfx('')();
      startGame();
    });
  }

  const howTo = $('#howTo');
  if (howTo) howTo.addEventListener('click', () => {
    ensureAudio();
    sfx('')();
    openHelpModal();
  });

  const help = $('#helpBtn');
  if (help) help.addEventListener('click', () => {
    ensureAudio();
    sfx('')();
    openHelpModal();
  });

  const sound = $('#soundBtn');
  if (sound) sound.addEventListener('click', () => {
    state.soundOn = !state.soundOn;
    if (state.soundOn) {
      ensureAudio();
      sfx('')();
    }
    updateSoundButton();
    saveGame();
  });

  const upgrade = $('#upgradeBtn');
  if (upgrade) upgrade.addEventListener('click', () => {
    sfx('')();
    openUpgrades();
  });

  const end = $('#endDayBtn');
  if (end) end.addEventListener('click', () => {
    sfx('')();
    closeUp();
  });

  const app = $('#app');
  if (app) {
    app.addEventListener('click', event => {
      const train = event.target.closest('[data-train]');
      if (train && !train.disabled) {
        ensureAudio();
        sfx('')();
        openTrainingSetup(train.dataset.train);
        return;
      }
      const action = event.target.closest('[data-action]');
      if (!action || action.disabled) return;
      ensureAudio();
      switch (action.dataset.action) {
        case 'clean': cleanGym(); break;
        case 'repair': repairGym(); break;
        case 'promote': promoteGym(); break;
        default: break;
      }
    });
}

function cleanGym() {
  if (state.time <= 0 || state.dayComplete) return;
  state.time -= 1;
  state.cleanliness = clamp(state.cleanliness + 34, 0, 100);
  sfx('')();
  spawnFloat(246, 590, '+CLEAN', TEAL);
  updateUI();
  saveGame();
  toast('Floor scrubbed. The mirror is smug again.', 'info', 'sparkle');
}

function repairGym() {
  if (state.time <= 0 || state.dayComplete) return;
  state.time -= 1;
  state.equipment = clamp(state.equipment + 29, 0, 100);
  sfx('')();
  spawnFloat(700, 570, '+TUNED', SUN);
  updateUI();
  saveGame();
  toast('Rack tightened. No more mysterious clanks.', 'info', 'wrench');
}

function promoteGym() {
  if (state.time <= 0 || state.dayComplete) return;
  if (state.cash < 15) {
    sfx('')();
    toast('You need $15 for flyers.', 'warn', 'info');
    return;
  }

